	setAlias(alias: string): this {
		super.setAlias(alias);
		return this;
	}

	/**
	 *
	 * @param baseLevel {number}
	 * @returns {ResourceAttributeEntity}
	 */
	setBaseLevel(baseLevel: number): this {
		super.setBaseLevel(baseLevel);
		return this;
